import { ProjectGrid } from "march/landing"

// barınaktaki dostlar: kapaklar büyük emojiler, kedi / köpek / kuş süzgeci; birine basınca "sahiplen" sayacı artar
// bir projenin biçimi: kapak bir görsel ya da düğüm
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; href?: string; cover: Node | { src: string; alt: string; width: number; height: number } }
const PETS = [
  { id: "pamuk", title: "Pamuk", category: "Kedi", year: "2 yaş", emoji: "🐱" },
  { id: "karabas", title: "Karabaş", category: "Köpek", year: "4 yaş", emoji: "🐶" },
  { id: "limon", title: "Limon", category: "Kuş", year: "1 yaş", emoji: "🐤" },
  { id: "tarcin", title: "Tarçın", category: "Kedi", year: "6 ay", emoji: "😺" },
  { id: "bulut", title: "Bulut", category: "Köpek", year: "3 yaş", emoji: "🐕" },
]

const Face = (p: { emoji: string }) => <div style={{ "font-size": "4rem", "text-align": "center", padding: "1.5rem" }} aria-hidden="true">{p.emoji}</div>

export function PetShelter() {
  let $adopted = 0
  const pets: Project[] = PETS.map((p) => ({ ...p, get cover() { return <Face emoji={p.emoji} /> as Node } }))
  return <div sx={{ flex: "col", gap: 3 }}>
    <strong>Sahiplenme isteği: {$adopted}</strong>
    <ProjectGrid projects={pets} cols={3} allLabel="Hepsi" onOpen={() => $adopted++} />
  </div>
}

import { ProjectGrid } from "march/landing"

// bir tasarım stüdyosunun işleri: fotoğraf kapaklar (boyutu ayrılmış, tembel yüklenir), süzgeç çipleri;
// kapağa basınca görsel büyük açılır (Lightbox)
// bir projenin biçimi: kapak bir görsel ya da düğüm
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; href?: string; cover: Node | { src: string; alt: string; width: number; height: number } }
const WORK: Project[] = [
  { id: "kapadokya", title: "Kapadokya Turizm", category: "Marka", year: 2026, summary: "Yeni kimlik ve rezervasyon sitesi.", cover: { src: "/media/dusk.jpg", alt: "Gün batımında vadi", width: 1200, height: 800 } },
  { id: "dalga", title: "Dalga Müzik", category: "Uygulama", year: 2026, summary: "Canlı dinleme odaları, iOS ve Android.", cover: { src: "/media/hadi-waves.jpg", alt: "Renkli dalgalar", width: 960, height: 540 } },
  { id: "aksam", title: "Akşam Sofrası", category: "Web", year: 2025, summary: "Restoran zinciri için sipariş sitesi.", cover: { src: "/media/dusk.jpg", alt: "Akşam ışığı", width: 1200, height: 800 } },
  { id: "ritim", title: "Ritim Festivali", category: "Marka", year: 2025, summary: "Afişler, bilet sayfası ve hareket.", cover: { src: "/media/hadi-waves.jpg", alt: "Festival renkleri", width: 960, height: 540 } },
]

export function StudioWork() {
  return <ProjectGrid projects={WORK} cols={2} allLabel="Tüm işler" filtersLabel="İşleri süz" />
}

import { ProjectGrid } from "march/landing"
import { Toggle, Card } from "march/ui"

// ProjectGrid'in bütün özellikleri bir arada: projeler (görsel ya da düğüm kapak, kategori, yıl, özet, bağlantı),
// süzgeçler, sütun, açma (onOpen), Lightbox, "Tümü" metni, süzgeç grubunun adı, kapak rozeti, süzme hareketi,
// giriş hareketi (reveal) ve sınıf
// bir projenin biçimi: kapak bir görsel ya da düğüm
type Project = { id: string; title: string; category?: string; year?: number | string; summary?: string; href?: string; cover: Node | { src: string; alt: string; width: number; height: number } }
const Art = (p: { color: string; label: string }) =>
  <div style={{ background: p.color, color: "#fff", "aspect-ratio": "4 / 3", display: "grid", "place-items": "center", "font-size": "2rem" }} aria-hidden="true">{p.label}</div>

// her çağrıda yeni kapak düğümleri: bir düğüm tek bir yerde durabilir
const work = (): Project[] => [
  { id: "atlas", title: "Atlas Banka", category: "Marka", year: 2026, summary: "Kimlik ve web sitesi.", cover: <Art color="#7c5cff" label="A" /> as Node },
  { id: "kite", title: "Kite uygulaması", category: "Uygulama", year: 2026, summary: "Seyahat planlayıcı.", cover: <Art color="#2bb8ff" label="K" /> as Node },
  { id: "lumen", title: "Lumen panosu", category: "Web", year: 2025, cover: { src: "/media/hadi-waves.jpg", alt: "Dalgalar", width: 960, height: 540 } },
  { id: "orbit", title: "Orbit konferansı", category: "Marka", year: 2025, summary: "Etkinlik kimliği.", cover: <Art color="#ff7a59" label="O" /> as Node, href: "#orbit" },
]

export function ProjectGridLab() {
  let $filters = true
  let $two = false
  let $motion = false
  let $ownArrow = false
  let $useOpen = true
  let $opened = "henüz yok"
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Toggle label="Süzgeçler" bind:value={$filters} />
        <Toggle label="İki sütun" bind:value={$two} />
        <Toggle label="Süzerken hareket" bind:value={$motion} />
        <Toggle label="Rozette yıl" bind:value={$ownArrow} />
        <Toggle label="Kendim açarım (onOpen)" bind:value={$useOpen} />
      </div>
      <p sx={{ color: "muted" }}>Açılan: {$opened}</p>
    </Card>
    {() => {
      // sinyaller burada okunur: değişince ızgara yeniden çizilir
      const filters = $filters, two = $two, motion = $motion, ownArrow = $ownArrow, useOpen = $useOpen
      return <ProjectGrid class="lab-grid" projects={work()} filters={filters} cols={two ? 2 : 3}
        onOpen={useOpen ? (p: Project) => { $opened = String(p.title) } : undefined} lightbox
        allLabel="Tümü" filtersLabel="Projeleri süz" motion={motion}
        arrow={ownArrow ? (p: Project) => <span>{String(p.year)}</span> : true}
        reveal={{ effect: "scale", stagger: 50 }} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ProjectGridLab } from "./ProjectGridLab.tsx"

// ProjectGridLab'in testleri: kaydedince Testler sekmesinde çalışır
test("dört kart; süzgeç grubunun adı ve Tümü + üç kategori çipi", () => {
  const s = renderTest(() => <ProjectGridLab />)
  expect(s.all(".lab-grid .m-pg-card").length).toBe(4)
  const group = s.get('.lab-grid [role="group"]')
  expect(group?.getAttribute("aria-label")).toBe("Projeleri süz")
  expect(group?.textContent).toContain("Tümü")
  expect(group?.textContent).toContain("Uygulama")
})

test("Marka çipi: yalnız iki marka işi görünür kalır (hareketsiz)", async () => {
  const s = renderTest(() => <ProjectGridLab />)
  await s.click("Marka")
  const shown = s.all(".lab-grid .m-pg-card").filter((c: Element) => !(c as HTMLElement).hidden)
  expect(shown.length).toBe(2)
})

test("başlığa basınca onOpen projeyi alır", async () => {
  const s = renderTest(() => <ProjectGridLab />)
  await s.click("Kite uygulaması")
  expect(s.find("Açılan: Kite uygulaması")).not.toBe(null)
})

test("anahtarlar: iki sütun ve rozette yıl", async () => {
  const s = renderTest(() => <ProjectGridLab />)
  await s.click("İki sütun")
  expect(s.get(".m-pg-cols-2")).not.toBe(null)
  await s.click("Rozette yıl")
  expect(s.all(".m-pg-go.is-own").length).toBe(4)
})
